<?php
require_once __DIR__.'/../../config/database.php';require_once __DIR__.'/../../includes/session.php';require_once __DIR__.'/../../includes/functions.php';require_once __DIR__.'/../../includes/admin_layout.php';if(!is_admin_logged_in())redirect('../../index.php');if(($_SESSION['admin_role']??'admin')!=='admin'){http_response_code(403);exit('Administrator access required.');}$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 if(!verify_csrf_token($_POST['csrf_token']??''))$error='Security token expired.';else{
  $id=(int)($_POST['id']??0);$decision=$_POST['decision']??'';$notes=trim($_POST['notes']??'');
  if(!in_array($decision,['approved','rejected'],true))$error='Invalid decision.';else{
   pg_query($conn,'BEGIN');$r=pg_query_params($conn,"SELECT * FROM student_information_requests WHERE id=$1 AND status='pending' FOR UPDATE",[$id]);
   if(!$r||!pg_num_rows($r)){pg_query($conn,'ROLLBACK');$error='Pending request not found.';}else{
    $request=pg_fetch_assoc($r);$ok=true;
    if($decision==='approved'){$data=json_decode($request['requested_data'],true)?:[];$ok=(bool)pg_query_params($conn,"UPDATE attendees SET full_name=$1,email=$2,phone=$3,course=$4,year_level=$5,section=$6,organization=concat_ws(' · ',$4,$5,$6),updated_at=NOW() WHERE id=$7",[$data['full_name']??'',$data['email']?:null,$data['phone']?:null,$data['course']??'',$data['year_level']??'',$data['section']??'',$request['attendee_id']]);}
    if($ok)$ok=(bool)pg_query_params($conn,'UPDATE student_information_requests SET status=$1,reviewed_by=$2,reviewed_at=NOW(),reviewer_notes=$3 WHERE id=$4',[$decision,$_SESSION['admin_id'],$notes,$id]);
    if($ok){pg_query($conn,'COMMIT');audit_log($conn,'student_information_request_'.$decision,'student_request',$id);redirect('index.php');}pg_query($conn,'ROLLBACK');$error='The request could not be processed.';
   }
  }
 }
}
$rows=pg_query($conn,"SELECT r.*,s.attendee_code,s.full_name student_name,a.full_name reviewer_name FROM student_information_requests r JOIN attendees s ON s.id=r.attendee_id LEFT JOIN admins a ON a.id=r.reviewed_by ORDER BY CASE r.status WHEN 'pending' THEN 0 ELSE 1 END,r.created_at DESC");admin_page_start('Information Requests','requests');?>
<div class="hero"><div><h2><i class="fas fa-inbox"></i> Student Information Requests</h2><p>Review requested profile corrections and retain a clear approval trail.</p></div></div><?php if($error):?><div class="alert error"><?=h($error)?></div><?php endif;?><div class="card"><div class="table-wrap"><table><thead><tr><th>Student</th><th>Requested Changes</th><th>Reason</th><th>Status / Reviewer</th><th>Decision</th></tr></thead><tbody><?php if($rows):while($r=pg_fetch_assoc($rows)):$data=json_decode($r['requested_data'],true)?:[];?><tr><td><strong><?=h($r['student_name'])?></strong><div class="help"><?=h($r['attendee_code'])?> · <?=h(date('M j, Y',strtotime($r['created_at'])))?></div></td><td><?php foreach($data as $key=>$value):?><div><strong><?=h(ucwords(str_replace('_',' ',$key)))?>:</strong> <?=h($value?:'—')?></div><?php endforeach;?></td><td><?=h($r['reason']?:'—')?></td><td><span class="badge <?=h($r['status'])?>"><?=h(ucfirst($r['status']))?></span><div class="help"><?=h($r['reviewer_name']?:'Not reviewed')?></div></td><td><?php if($r['status']==='pending'):?><form method="post" class="actions"><?=csrf_field()?><input type="hidden" name="id" value="<?=(int)$r['id']?>"><input name="notes" placeholder="Remarks"><button class="btn small" name="decision" value="approved">Approve</button><button class="btn small danger" name="decision" value="rejected">Reject</button></form><?php else:?><?=h($r['reviewer_notes']?:'—')?><?php endif;?></td></tr><?php endwhile;endif;if(!$rows||pg_num_rows($rows)===0):?><tr><td colspan="5" class="empty">No information requests.</td></tr><?php endif;?></tbody></table></div></div><?php admin_page_end();?>
